window.kbPageData["views/entry/k-24fa7513617a5170"] = {"key":"entry/k-24fa7513617a5170","state":{"route":"entry/k-24fa7513617a5170"},"node":{"id":"k-24fa7513617a5170","mode":"k","title":"星期的七天周期","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["日期相差天数对七取余确定星期偏移","星期以七天为周期","任意连续七天包含每个星期几各一次"],"qs":["国考 2024 副省级 行测#75","国考 2024 地市级 行测#69","国考 2024 行政执法 行测#68","国考 2025 副省级 行测#75","江苏 2025 A类 行测#69"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":3,"repeatPositions":2,"directorySummary":"星期每7天循环一次。从已知日期向后推时，将相差天数除以7，余几就将星期向后推几天。","review":{"definition":"星期每7天循环一次。从已知日期向后推时，将相差天数除以7，余几就将星期向后推几天。","explanation":"题中的“每隔4天”表示两次理疗之间空出4天，因此每5天理疗一次。把起始日从7月2日改到3日，6次理疗的星期均顺延一天。第二种排法没有星期六的理疗，所以第一种排法没有星期五的理疗。第一种排法只覆盖6个不同的星期，其日期相对7月2日的日差除以7后，余数依次是0、5、3、1、6、4，唯一缺少2。因此7月2日后两天是星期五，7月2日是星期三。7月31日比2日晚29天，余1，故为星期四，对应A项。","references":[],"evidence":"如果他7月3日去，则7月的理疗只有1次在星期日，其余都在工作日","disposition":"独立词条","basis":"据原题和解析编释。","title":"星期的七天周期","related":[],"examFocus":{"国考 2024 副省级 行测#75":"把9月和10月各拆成整周与余天，比较余天的活动次数，再利用星期周期推算年末的活动日期。","国考 2025 副省级 行测#75":"把前16天拆成整周与余天，结合工作日和周末的日营业额判断余天的星期分布。","江苏 2025 A类 行测#69":"先弄清“每隔4天”的计数口径，再按七天周期比较两种起始日期下落在周六和周日的理疗次数。"}},"readings":[{"origin":"k-24fa7513617a5170","title":"星期的七天周期","qs":["江苏 2025 A类 行测#69"],"definition":"星期每7天循环一次。从已知日期向后推时，将相差天数除以7，余几就将星期向后推几天。","explanation":"题中的“每隔4天”表示两次理疗之间空出4天，因此每5天理疗一次。把起始日从7月2日改到3日，6次理疗的星期均顺延一天。第二种排法没有星期六的理疗，所以第一种排法没有星期五的理疗。第一种排法只覆盖6个不同的星期，其日期相对7月2日的日差除以7后，余数依次是0、5、3、1、6、4，唯一缺少2。因此7月2日后两天是星期五，7月2日是星期三。7月31日比2日晚29天，余1，故为星期四，对应A项。","evidence":"如果他7月3日去，则7月的理疗只有1次在星期日，其余都在工作日","doubt":"","references":[]},{"origin":"k-2c9c51b05f428381","title":"星期的七天周期","qs":["国考 2024 行政执法 行测#68"],"definition":"星期每七天循环一次，任意连续七天各包含一次星期一至星期日。两日期的星期偏移由相隔天数除以7的余数决定。","explanation":"每连续28天，小张都参加12次活动。9月前28天之外的两天须参加1次，10月后28天之外的三天须参加2次。因此9月29日至10月3日这连续五天必须同时包含周二、周五和周日，只有从周五开始才满足。9月30日是周六，12月31日在其后92天，92除以7余1，所以12月31日是周日，也是当年最后一次活动日。","evidence":"小张连续7天参加3次社团活动","doubt":"","references":[]},{"origin":"k-365f51843437bcd8","title":"星期的七天周期","qs":["国考 2025 副省级 行测#75"],"definition":"星期按七天循环。任意连续七天中，星期一到星期日各出现一次，相差整七天的日期对应同一星期几。","explanation":"本题每个七天周期的营业额为5×1＋2×2＝9万元。3日至16日恰好覆盖两个周期，共18万元，因此1日和2日合计4万元，两天都必须是周末。连续两天同为周末只能是星期六接星期日，所以1日是星期六，相隔七天的8日也是星期六。","evidence":"连续的14天（3日至16日）包含星期一至星期日各2个","doubt":"","references":[]},{"origin":"k-94610e175b3e4f5a","title":"星期的七天周期","qs":["国考 2024 副省级 行测#75"],"definition":"星期按七天循环，任意连续七天各包含一次周一至周日。按固定星期几重复的活动，在每个连续七天内发生的次数相同。","explanation":"小张每周二、周五、周日骑行，连续28天必有12次。扣除9月前28天和10月后28天，9月末两天须有1次，10月初三天须有2次。满足这两个条件的五天依次是周五、周六、周日、周一、周二，因此9月30日为周六。12月31日距这天92天，比13整周多1天，恰逢周日，选A。","evidence":"小张连续7天参加3次社团活动","doubt":"","references":[]},{"origin":"k-efb76cdb22a3b5f1","title":"星期的七天周期","qs":["国考 2024 地市级 行测#69"],"definition":"星期按七天循环，任意连续七天恰好包含一次星期一至星期日。若活动固定在每周的若干天举行，每段完整的七天内，活动次数都等于固定活动日的天数。","explanation":"本题固定在周二、周五和周日骑行，每28天正好骑行12次。扣除9月前28天和10月后28天后，9月末两天需骑行1次，10月初三天需骑行2次。合起来，9月29日至10月3日这连续五天必须同时覆盖周五、周日和周二，只有从周五开始才满足，因此9月29日是周五。","evidence":"小张连续7天参加3次社团活动","doubt":"","references":[]}]},"questions":{"国考 2024 副省级 行测#75":{"paper":"国考 2024 副省级 行测","n":75,"mod":"数量关系","src":["a566fec37e508ca7f975.pdf",14],"asrc":["a475ecf57d968bc14cd6.pdf",23],"card":"aa55d9f73af733cc0b1ffa5e","links":[{"id":"k-24fa7513617a5170","role":"解题依据","why":"每个七天周期都覆盖三个固定活动日，可据此计算整周的活动次数。"}]},"国考 2024 地市级 行测#69":{"paper":"国考 2024 地市级 行测","n":69,"mod":"数量关系","src":["92d0b72e86a6a33d568d.pdf",12],"asrc":["e1792c53900a45f1b9fa.pdf",21],"card":"6f20278fb310ec4c8aa778a3","links":[{"id":"k-24fa7513617a5170","role":"解题依据","why":"任意连续七天各包含一次周二、周五和周日，因此每个完整周期的活动次数相同。"}]},"国考 2024 行政执法 行测#68":{"paper":"国考 2024 行政执法 行测","n":68,"mod":"数量关系","src":["dfddc59dc6e7d9da5d71.pdf",12],"asrc":["6493f3a6a55c38431852.pdf",21],"card":"c8340eb2a10cbcfa2e1f166b","links":[{"id":"k-24fa7513617a5170","role":"解题依据","why":"任意连续七天都覆盖一轮固定活动日，日期相隔天数除以七的余数决定星期偏移。"}]},"国考 2025 副省级 行测#75":{"paper":"国考 2025 副省级 行测","n":75,"mod":"数量关系","src":["ffe12c35a46d4df574ec.pdf",13],"asrc":["ff0b352b44d417525086.pdf",23],"card":"3dba14b22c1e8770554d3e9d","links":[{"id":"k-24fa7513617a5170","role":"解题依据","why":"任意连续七天包含每个星期日序各一次，相隔七天的日期对应同一星期。"}]},"江苏 2025 A类 行测#69":{"paper":"江苏 2025 A类 行测","n":69,"mod":"数量关系","src":["98687766ac277f427cd6.pdf",14],"asrc":["4fe8e0544dd7b47699d2.pdf",22],"card":"e23134afe14b0e2c9b3b3ced","links":[{"id":"k-24fa7513617a5170","role":"解题依据","why":"星期每七天循环一次，可据日差推算理疗日期对应的星期。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-24fa7513617a5170":[["国考 2024 副省级 行测#75","国考 2024 地市级 行测#69","国考 2024 行政执法 行测#68"],["国考 2025 副省级 行测#75"],["江苏 2025 A类 行测#69"]]}};
